      'H-13': ["A Tüdő Shu-pontja", "Shu-pont (Tüdő)", "A háton, a 3. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett.", "Hagyományosan a mellkas és a légzés ellazítására.", "Tenyérrel dörzsölve vagy társ által hüvelykujjal, 1 percig.", ""],
      'H-15': ["A Szív Shu-pontja", "Shu-pont (Szív)", "A háton, az 5. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett.", "Hagyományosan lecsendesedéshez, este.", "Társ által, hüvelykujjal vagy meleg tenyérrel, 1 percig.", ""],
      'H-17': ["A rekeszizom Shu-pontja", "Shu-pont (rekeszizom) · a vér mesterpontja", "A háton, a 7. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett (kb. a lapockák alsó csúcsának magasságában).", "Hagyományosan a hát közepének és a légzés ellazítására.", "Társ által hüvelykujjal, kilégzéskor nyomva, 1 percig.", ""],
      'H-18': ["A Máj Shu-pontja", "Shu-pont (Máj)", "A háton, a 9. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett.", "Hagyományosan feszültség oldására, a hát közepén.", "Társ által hüvelykujjal vagy teniszlabdán fekve, 1 percig.", ""],
      'H-20': ["A Lép Shu-pontja", "Shu-pont (Lép)", "A háton, a 11. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett.", "Hagyományosan az emésztés és az erőnlét támogatására.", "Meleg tenyérrel dörzsölve, 1 percig.", ""],
      'H-21': ["A Gyomor Shu-pontja", "Shu-pont (Gyomor)", "A háton, a 12. hátcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett.", "Hagyományosan az emésztés támogatására.", "Meleg tenyérrel dörzsölve, 1 percig.", ""],
      'H-25': ["A Vastagbél Shu-pontja", "Shu-pont (Vastagbél)", "A derékon, a 4. ágyékcsigolya tövisnyúlványa alatt, 1,5 cunnal a gerinc mellett (a csípőlapát tetejének vonalában).", "Hagyományosan a derék ellazítására és a has közérzetére.", "Két hüvelykkel vagy ököllel ütögetve, 1 percig.", ""],
      'Kor-12': ["A test oszlopa", "", "A hát középvonalán, a 3. hátcsigolya tövisnyúlványa alatt.", "Hagyományosan a felső hát melegítésére, tartásra.", "Meleg tenyérrel tartva vagy körözve, 1 percig.", ""],
      'Véb-11': ["Égi forrás", "", "A lapocka közepén lévő mélyedésben (a lapockatövis alatti gödör közepén).", "Hagyományosan a lapocka és a váll ellazítására, képernyőmunka után.", "Társ által hüvelykujjal, vagy a falnak dőlve teniszlabdával, 1 percig.", ""],
      'Vab-10': ["Három mérföld a karon", "", "Az alkar hüvelykujj felőli oldalán, 2 cunnal a könyökránc külső vége (Vab-11) alatt.", "Hagyományosan az alkar és a kar ellazítására, sok gépelés után.", "Erős hüvelykujjas nyomás vagy körzés, 1 percig.", ""],
      'Vab-15': ["Vállcsúcs-szöglet", "Találkozási pont", "A váll elülső részén, a vállcsúcs alatti elülső mélyedésben, amely a kar oldalra emelésekor jelenik meg.", "Hagyományosan a váll ellazítására és mozgékonyságára.", "Hüvelykujjal vagy ujjbegyekkel körözve, közben a vállat lassan forgatva, 1 percig.", ""],
      'Hm-14': ["Vállcsúcs-hasadék", "", "A váll hátsó részén, a vállcsúcs alatti hátsó mélyedésben, amely a kar oldalra emelésekor jelenik meg.", "Hagyományosan a váll ellazítására, a Vab-15 párjaként.", "Ujjbegyekkel körözve, a vállat forgatva, 1 percig.", ""],
      'Szb-7': ["Nagy domb", "Yuan-pont · Föld-pont", "A csukló belső oldalán, a csuklóránc közepén, a két ín között.", "Hagyományosan lecsendesedéshez, és a csukló ellazítására gépelés után.", "Hüvelykujjal gyengéden, 30–60 másodpercig.", ""],
      'Hm-4': ["Yang-tó", "Yuan-pont", "A csukló kézhát felőli oldalán, a csuklóránc közepén lévő mélyedésben (az ujjfeszítő ín kisujj felőli oldalán).", "Hagyományosan a kéz melegítésére, a csukló ellazítására.", "Ujjbeggyel körözve vagy a két csuklót egymáshoz dörzsölve, 1 percig.", ""],
      'T-6': ["A legnagyobb nyílás", "Xi-pont (réspont)", "Az alkar belső-hüvelykujj felőli oldalán, 7 cunnal a csuklóránc fölött, a T-5 és a T-9 közötti vonalon.", "Hagyományosan a légzés és a torok környékének ellazítására.", "Hüvelykujjal erősebben, 1 percig.", ""],
      'Gy-34': ["Gerendadomb", "Xi-pont (réspont)", "A comb elülső-külső oldalán, 2 cunnal a térdkalács külső-felső széle fölött.", "Hagyományosan a térd és a gyomortáj közérzetére.", "Erős hüvelykujjas nyomás, 1 percig.", ""],
      'Gy-35': ["Borjúorr", "", "Behajlított térdnél a térdkalács alatti külső mélyedésben (a „térd külső szeme”).", "Hagyományosan a térd melegítésére és mozgatására.", "Ülve, behajlított térddel, ujjbegyekkel körözve, 1 percig.", ""],
      'Eh-30': ["Ugrás köre", "Találkozási pont", "A farizmon, a nagytompor és a keresztcsont alja közötti vonal külső és középső harmadának határán.", "Hagyományosan a csípő és a far ellazítására, hosszú ülés után.", "Oldalt fekve vagy állva könyökkel, ököllel vagy teniszlabdával, 1–2 percig.", ""],
      'Eh-39': ["Függő harang", "A velő mesterpontja", "A lábszár külső oldalán, 3 cunnal a külső bokacsúcs fölött, a szárkapocscsont elülső szélén.", "Hagyományosan a lábszár és a nyak oldalának ellazítására.", "Hüvelykujjal, 1 percig.", ""],
      'Eh-40': ["Domb romjai", "Yuan-pont", "A külső bokacsúcs előtt és alatt lévő mélyedésben.", "Hagyományosan a boka ellazítására és mozgatására.", "Ujjbeggyel körözve, közben a bokát lassan forgatva, 1 percig.", ""],
      'Eh-41': ["Könnyhez közeli (lábon)", "Fa-pont · nyitópont (Övér)", "A lábháton, a 4. és 5. lábközépcsont találkozása előtt, a kislábujj feszítőínének külső oldalán.", "Hagyományosan a lábfej és a test oldalsó vonalának ellazítására.", "Hüvelykujjal, 30–60 másodpercig.", ""],
      'H-57': ["A hegy tartója", "", "A vádli hátsó oldalán, a két ikerizomhas alatt kialakuló csúcsos mélyedésben, a térdhajlat és a sarok között félúton.", "Hagyományosan a vádli ellazítására, sok állás vagy séta után.", "Hüvelykujjal vagy ülve a másik térdre támasztva, 1 percig.", "Visszeres területen ne masszírozz."],
      'H-62': ["Kiterjesztett ér", "Nyitópont (Yang sarok-ér)", "Közvetlenül a külső bokacsúcs alatt, a mélyedésben.", "Hagyományosan a boka ellazítására és a nap végi lecsendesedéshez.", "Ujjbeggyel gyengéden, 30–60 másodpercig.", ""],
      'V-6': ["Ragyogó tenger", "Nyitópont (Yin sarok-ér)", "Közvetlenül a belső bokacsúcs alatt, a mélyedésben.", "Hagyományosan esti lecsendesedéshez, alvás előtt.", "Ülve, ujjbeggyel gyengéden, 1 percig, lassú kilégzéssel.", ""],
      'V-7': ["Visszatérő áramlás", "Fém-pont (antik Shu)", "A lábszár belső oldalán, 2 cunnal a belső bokacsúcs fölött, az Achilles-ín elülső szélén.", "Hagyományosan a lábszár és a boka ellazítására, melegítésére.", "Hüvelykujjal, 1 percig.", ""],
      'Lh-4': ["Nagyapa és unoka", "Lo-pont · nyitópont (Áthatoló ér)", "A láb belső szélén, az 1. lábközépcsont alapja előtt-alatt, a talp és a lábhát bőrének határán.", "Hagyományosan a lábfej és a has közérzetére.", "Hüvelykujjal a csont alá nyomva, 1 percig.", ""],
      'M-8': ["Hajlati forrás", "Víz-pont (antik Shu)", "Behajlított térdnél a térdránc belső végén, az inak előtti mélyedésben.", "Hagyományosan a térd belső oldalának ellazítására.", "Ülve, behajlított térddel, hüvelykujjal, 1 percig.", ""]
